// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/**
 * @type {Object.<string, { value: string, backgroundColor?: string }>} Mapea coordenadas (e.g., "A1") a su contenido y estilo actual.
 */
let estado = {}; 
const CLAVE = "app";

function cargar() { try { const s = localStorage.getItem(CLAVE); if (s) estado = JSON.parse(s); } catch (e) {} }
function guardar() { try { localStorage.setItem(CLAVE, JSON.stringify(estado)); } catch (e) {} }

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el estado interno de una celda específica.
 * @param {string} coordenada - La clave de la celda (ej: "B5").
 * @param {string} valor - El nuevo contenido escrito por el usuario.
 */
function actualizarCelda(coordenada, valor) {
    if (!estado[coordenada]) {
        // Inicializar estructura si es la primera vez que se toca esta celda
        estado[coordenada] = { value: "", backgroundColor: "" };
    }
    estado[coordenada].value = String(valor); 
}

/**
 * Establece el color de fondo de una celda en el estado.
 * @param {string} coordenada - La clave de la celda (ej: "B5").
 * @param {string} color - El código hexadecimal del color (#RRGGBB).
 */
function establecerColorFondo(coordenada, color) {
    if (!estado[coordenada]) {
        estado[coordenada] = { value: "", backgroundColor: "" };
    }
    estado[coordenada].backgroundColor = color;
}


/**
 * Evalúa una fórmula de estilo Excel en el estado actual del sistema.
 * @param {string} formula - La fórmula ingresada (debe empezar con '=').
 * @param {Object.<string, any>} state - El objeto de estado global (estado[coordenada] = {value: ..., backgroundColor: ...}).
 * @returns {string} El resultado calculado como cadena, o la fórmula original si no es válida.
 */
function evalFormula(formula, state) {
    if (!formula || !formula.startsWith('=')) {
        return formula; // No es una fórmula, devolverlo tal cual.
    }

    let expression = formula.substring(1).trim();

    // 1. Manejo de SUMA()
    const sumMatch = expression.match(/^SUMA\((.*)\)$/i);
    if (sumMatch) {
        const args = sumMatch[1];
        let valuesToSum = [];

        // Identificar argumentos separados por ; o espacios, manejando rangos A1:A3
        const parts = args.split(/[;,]\s*|\s+/).filter(p => p);

        for (const part of parts) {
            if (!part) continue;

            if (part.includes(':')) {
                // Rango simple vertical (e.g., A1:A3)
                const [startRef, endRef] = part.split(':').map(r => r.toUpperCase());

                if (startRef[0] !== endRef[0]) continue; // Debe ser la misma columna

                const startRow = parseInt(startRef.substring(startRef.length - 1));
                const endRow = parseInt(endRef.substring(endRef.length - 1));
                const colChar = startRef[0];

                for (let r = startRow; r <= endRow; r++) {
                    const key = colChar + r;
                    if (state[key] && typeof state[key].value === 'string' && !isNaN(parseFloat(state[key].value)))) {
                        valuesToSum.push(parseFloat(state[key].value));
                    }
                }
            } else {
                // Celda suelta (e.g., B2)
                const key = part.toUpperCase();
                if (state[key] && typeof state[key].value === 'string' && !isNaN(parseFloat(state[key].value)))) {
                    valuesToSum.push(parseFloat(state[key].value));
                }
            }
        }

        const total = valuesToSum.reduce((acc, val) => acc + val, 0);
        return total.toString();
    }


    // 2. Manejo de Operaciones Aritméticas Simples (Ej: =A1-B1, =A1*B1)
    const refRegex = /([A-Z]+[0-9]+)/g;
    let expressionString = expression.replace(refRegex, (match) => {
        // Reemplaza las referencias de celda con sus valores numéricos actuales para poder evaluar la expresión JS
        const key = match.toUpperCase();
        const value = state[key] && typeof state[key].value === 'string' ? parseFloat(state[key].value) : NaN;
        return isNaN(value) ? '0' : value;
    });

    try {
        // Usamos new Function() de forma controlada.
        const result = new Function('return ' + expressionString);
        let resultValue = parseFloat(result()).toString();
        // Si el resultado es NaN (por ejemplo, si la fórmula está incompleta o no numérica), devolver la fórmula original.
        if (isNaN(parseFloat(result()))) {
             return formula;
        }
        return resultValue;
    } catch (e) {
        console.error("Error al evaluar la expresión:", e);
        // Si falla la evaluación, devolvemos la fórmula original para que el usuario la vea.
        return formula; 
    }
}

// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    const rows = 20;
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(''); // A-J (10 chars)

    for (let r = 1; r <= rows; r++) {
        // Usamos data-row para seleccionar las filas de manera más robusta si el DOM cambia.
        const rowElement = tableBody.querySelector(`[data-row="${r}"]`);
        if (!rowElement) continue;

        for (let c = 0; c < columns.length; c++) {
            const columnaChar = columns[c];
            const coordenada = columnaChar + r;
            const cellElement = rowElement.querySelector(`[data-cell="${coordenada}"]`);

            if (cellElement) {
                // Obtener el estado, inicializando si es necesario
                let stateData = estado[coordenada] || { value: "", backgroundColor: "" };

                // 1. Actualizar el contenido textual
                const contenido = stateData.value; 
                let contenidoMostrar = contenido;

                if (contenido.startsWith('=')) {
                    contenidoMostrar = evalFormula(contenido, estado);
                }

                cellElement.textContent = contenidoMostrar;

                // 2. Aplicar el fondo de color guardado en estado
                if (stateData.backgroundColor) {
                    cellElement.style.backgroundColor = stateData.backgroundColor;
                } else {
                    // Limpiar fondo si no está definido o si es una celda nueva sin color asignado
                    cellElement.style.backgroundColor = ''; 
                }
            }
        }
    }
}

/**
 * Muestra el menú contextual para la selección de color en la celda dada.
 * @param {string} coordenada - Coordenada de la celda (ej: "A1").
 * @param {HTMLElement} targetElement - El elemento TD que disparó el evento.
 */
function showColorMenu(coordenada, targetElement) {
    const container = document.querySelector('.spreadsheet-container');
    let menu = document.getElementById('colorContextMenu');

    if (!menu) {
        // Crear el menú si no existe (debe estar en index.html o crearlo aquí)
        // Para simplicidad, lo crearemos y lo dejaremos flotando globalmente.
        menu = document.createElement('div');
        menu.id = 'colorContextMenu';
        menu.className = 'context-menu';
        document.body.appendChild(menu);
    }

    const menuElement = document.getElementById('colorContextMenu');
    if (!menuElement) return;


    // Limpiar opciones anteriores
    Array.from(menuElement.querySelectorAll('.color-option')).forEach(el => el.remove());

    // Crear opción de color por defecto (ej: rojo para la prueba)
    const defaultColor = '#FF0000'; 
    let htmlContent = `
        <div class="context-menu-header">Estilo de Celda</div>
        <div class="color-option" data-color="${defaultColor}">
            <span style="font-weight: bold;">Rojo (Prueba)</span>
            <div class="color-swatch" style="background-color: ${defaultColor};"></div>
            <button onclick="applyColor('${coordenada}', '${defaultColor}')">Aplicar</button>
        </div>
    `;

    // Añadir opciones básicas de color (blanco, negro, etc.)
    htmlContent += `
        <div class="color-option" data-color="#ffffff">
            <span>Blanco</span>
            <div class="color-swatch" style="background-color: #ffffff;"></div>
            <button onclick="applyColor('${coordenada}', '#ffffff')">Aplicar</button>
        </div>
        <div class="color-option" data-color="#000000">
            <span>Negro</span>
            <div class="color-swatch" style="background-color: #000000;"></div>
            <button onclick="applyColor('${coordenada}', '#000000')">Aplicar</button>
        </div>
    `;

    menuElement.innerHTML = htmlContent;


    // Posicionar el menú justo debajo del elemento clicado
    const rect = targetElement.getBoundingClientRect();
    menuElement.style.top = `${rect.bottom + window.scrollY}px`;
    menuElement.style.left = `${rect.left + window.scrollX}px`;

    // Hacer visible el menú
    menuElement.style.display = 'block';

    // Guardar la coordenada actual en el elemento (para que pueda ser usada por las funciones anónimas)
    menuElement.dataset.currentCoord = coordenada;
}


/**
 * Aplica un color de fondo a una celda y guarda el estado.
 * @param {string} coordenada - La clave de la celda.
 * @param {string} color - El código hexadecimal del color.
 */
function applyColor(coordenada, color) {
    // 1. LÓGICA: Establecer el nuevo fondo en el estado
    establecerColorFondo(coordenada, color);

    // 2. PERSISTENCIA: Guardar el cambio en local storage
    guardar();

    // 3. DIBUJO: Refrescar la vista para aplicar el estilo visualmente
    render();
}


/**
 * Maneja eventos de la tabla: input (contenido) y contextmenu (color).
 */
function conectar() {
    const tableContainer = document.getElementById('spreadsheetTable');

    if (tableContainer) {
        // 1. Delegación para cambios de contenido (Input)
        tableContainer.addEventListener('input', (event) => {
            let target = event.target;

            // Verificamos que el evento provenga de una celda editable (<td>) y no sea la cabecera
            if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD' && !target.closest('.header-row')) {
                const coordenada = target.getAttribute('data-cell');
                // Usamos textContent para obtener el valor después de la edición
                const nuevoValor = target.textContent; 

                actualizarCelda(coordenada, nuevoValor);
                guardar();
                render();
            }
        });

        // 2. Delegación para menú contextual (Right Click)
        tableContainer.addEventListener('contextmenu', (event) => {
            event.preventDefault(); // Previene el menú nativo del navegador

            let target = event.target;

            // Verificamos que el evento provenga de una celda editable y no sea la cabecera
            if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD' && !target.closest('.header-row')) {
                const coordenada = target.getAttribute('data-cell');
                showColorMenu(coordenada, target);
            }
        });

        // 3. Manejo de foco/selección (Opcional pero recomendado para mejorar UX)
        tableContainer.addEventListener('focusin', (event) => {
             let target = event.target;
             if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD' && !target.closest('.header-row')) {
                 // Marcar visualmente la celda activa en el DOM para que CSS pueda capturarla
                 const cellsInRow = target.parentNode.querySelectorAll('td');
                 cellsInRow.forEach(cell => cell.removeAttribute('data-selected'));
                 target.setAttribute('data-selected', 'true');
             }
        });

         tableContainer.addEventListener('focusout', (event) => {
             let target = event.target;
             if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD' && !target.closest('.header-row')) {
                 // Quitar la clase de selección cuando pierden el foco
                 target.removeAttribute('data-selected');
             }
         });

    }
}

