        button.style.backgroundColor = color;
        button.className = 'color-picker-option';
        button.onclick = () => applyBackgroundColor(coordinate, color);
        menu.appendChild(button);
    });

    // Mostrar el menú
    menu.style.display = 'block';

    // Añadir un listener para cerrar el menú al hacer clic fuera de él
    document.addEventListener('click', closeColorMenu, { once: true });
}

function closeColorMenu() {
