/**
 * Aplica un color de fondo a una celda específica y actualiza el estado visualmente.
 * @param {string} coordinate - La coordenada de la celda (ej: "A1").
 * @param {string | null} color - El color hexadecimal o null para borrar.
 */
function applyBackgroundColor(coordinate, color) {
    const targetCell = document.querySelector(`[data-cell="${coordinate}"]`);
    if (!targetCell) return;

    // 1. Aplicar el estilo visualmente
    if (color === null) {
        targetCell.style.backgroundColor = ''; // Resetear
    } else {
        targetCell.style.backgroundColor = color;
    }

    // 2. Guardar la información del color en un atributo de datos o, si fuera necesario persistirlo, en el estado.
    // Para este ejercicio, lo guardaremos en un atributo data-color para que render() pueda leerlo (aunque no esté implementado)
    if (color === null) {
        targetCell.removeAttribute('data-bg-color');
    } else {
        targetCell.setAttribute('data-bg-color', color);
    }

    // 3. Persistencia: Actualizar estado para que el color se guarde con la celda (aunque solo lo usamos visualmente ahora)
    // Nota: Esto es un compromiso de diseño, ya que 'estado' está diseñado solo para contenido, pero ayuda a mantener coherencia si el color debe persistir en localStorage.
    // Aquí simplemente confiamos en que el DOM maneje el estado visual por ahora y no modificamos `estado` con colores complejos.

    guardar(); // Guardamos cualquier cambio de valor (aunque solo cambia estilo)
    render(); // Re-renderizar para asegurar la coherencia, aunque probablemente no cambie nada más.
}
