### FUNCION: showColorMenu
```javascript
/**
 * Muestra un menú de contexto para cambiar el fondo del color en la celda dada.
 * @param {Event} e - El evento de ratón derecho.
 * @param {HTMLElement} targetElement - La celda (TD) que fue clickeada.
 */
function showColorMenu(e, targetElement) {
    // Prevenir cualquier comportamiento predeterminado del menú contextual.
    e.preventDefault();

    // 1. Crear y posicionar el menú de color temporalmente.
    let menu = document.createElement('div');
    menu.className = 'context-color-menu';
    menu.style.position = 'fixed';
    menu.style.left = `${e.clientX}px`;
    menu.style.top = `${e.clientY}px`;
    menu.style.zIndex = '1000';

    // Contenido del menú: un selector de color simple (ejemplo)
    let colorPickerHTML = `
        <div class="color-option" data-color="#FFFFFF" style="background-color: #FFFFFF; width: 30px; height: 20px; border: 1px solid #ccc;"></div>
        <div class="color-option" data-color="#FF0000" style="background-color: #FF0000; width: 30px; height: 20px; border: 1px solid #ccc;"></div>
        <div class="color-option" data-color="#008000" style="background-color: #008000; width: 30px; height: 20px; border: 1px solid #ccc;"></div>
        <input type="color" id="colorInput" value="#FFFFFF" style="cursor: pointer; vertical-align: middle; margin-left: 5px;">
    `;
    menu.innerHTML = `
        <div style="display: flex; align-items: center; padding: 5px;">Color de Fondo</div>
        ${colorPickerHTML}
    `;

    document.body.appendChild(menu);

    const colorOptions = menu.querySelectorAll('.color-option');
    const colorInput = document.getElementById('colorInput');

    // 2. Manejar la selección de colores predefinidos
    colorOptions.forEach(option => {
        option.addEventListener('click', () => {
            const color = option.getAttribute('data-color');
            applyBackgroundColor(targetElement, color);
            menu.remove(); // Remover el menú al seleccionar un color
        });
    });

    // 3. Manejar la selección del input de color (color picker nativo)
    colorInput.addEventListener('input', () => {
        const color = colorInput.value;
        applyBackgroundColor(targetElement, color);
        menu.remove(); // Remover el menú al seleccionar un color
    });

    // 4. Limpieza: Eliminar el menú si se hace clic fuera de él.
    document.addEventListener('click', (e) => {
        if (!menu.contains(e.target)) {
            menu.remove();
        }
    }, { once: true }); // Usar {once: true} para limpiarlo después del primer click fuera.
}

/**
 * Aplica el color de fondo al elemento TD y actualiza el estado visualmente.
 * @param {HTMLElement} targetElement - El TD que recibirá el color.
 * @param {string} color - El código hexadecimal del color.
 */
function applyBackgroundColor(targetElement, color) {
    // 1. Aplicar estilo CSS al elemento DOM
    targetElement.style.backgroundColor = color;

    // Nota: No actualizamos 'estado' ya que solo almacena texto. Esto es puramente visual.
}
