/**
 * Limpia todo el contenido de la columna seleccionada en el estado y el DOM.
 */
function clearColumnContent(colChar) {
    if (!estadoSeleccionColumna || estadoSeleccionColumna !== colChar) return;

    const rows = 20;
    let changesMade = false;

    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        if (estado[key] !== undefined && estado[key] !== "") {
            // Limpiar el contenido de la celda en el estado.
            actualizarCelda(key, "");
            changesMade = true;
        }
    }

    if (changesMade) {
        guardar();
        render();
        console.log(`Contenido de la columna ${colChar} limpiado.`);
    } else {
        console.log(`La columna ${colChar} ya estaba vacía.`);
    }
}

/**
 * Elimina completamente todos los datos de una columna del estado y el DOM.
 */
function deleteColumn(colChar) {
    if (!estadoSeleccionColumna || estadoSeleccionColumna !== colChar) return;

    const rows = 20;
    let keysToDelete = [];
    for (let r = 1; r <= rows; r++) {
        keysToDelete.push(colChar + r);
    }

    // Eliminar todas las referencias de esta columna del estado
    keysToDelete.forEach(key => delete estado[key]);

    guardar();
    render();
    console.log(`Columna ${colChar} eliminada exitosamente.`);

    // Resetear la selección y los controles después de borrar
    estadoSeleccionColumna = null;
    document.getElementById('selectedColumnDisplay').textContent = 'Ninguna columna seleccionada';
    document.getElementById('clearColumnButton').disabled = true;
    document.getElementById('deleteColumnButton').disabled = true;
}

/**
 * Cambia el color de fondo de todas las celdas en la columna seleccionada (visual).
 */
function setBackgroundColor(colChar, color) {
    // Esta interacción es visual y no afecta al estado de datos, pero cumple con el requisito.
    const tableBody = document.getElementById('spreadsheetTable').querySelector('tbody');
    if (!tableBody) return;

    const rows = 20;
    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        const cellElement = tableBody.querySelector(`[data-cell="${key}"]`);
        if (cellElement) {
            // Aplicar el estilo de fondo. Limpiamos cualquier color previo y aplicamos el nuevo.
            cellElement.style.backgroundColor = color; 
        }
    }
    console.log(`Fondo de la columna ${colChar} cambiado a ${color}.`);
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    const rows = 20;
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(''); // A-J (10 chars)

    for (let r = 1; r <= rows; r++) {
        const rowElement = tableBody.querySelector(`tr:nth-child(${r})`);
        if (!rowElement) continue;

        for (let c = 0; c < columns.length; c++) {
            const columnaChar = columns[c];
            const coordenada = columnaChar + r;
            const cellElement = rowElement.querySelector(`[data-cell="${coordenada}"]`);

            if (cellElement) {
                // Obtener el valor de estado, si no existe, es una cadena vacía.
                const contenido = estado[coordenada] || ""; 
                let contenidoMostrar = contenido;

                // Evaluar la fórmula antes de mostrarla en el DOM
                if (contenido.startsWith('=')) {
                    contenidoMostrar = evalFormula(contenido, estado);
                }

                // Actualizar el DOM con el contenido calculado o original.
                cellElement.textContent = contenidoMostrar;
            }
        }
    }
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tableContainer = document.getElementById('spreadsheetTable');

    // 1. Listener para edición de celdas (EXISTENTE)
    if (tableContainer) {
        tableContainer.addEventListener('input', (event) => {
            let target = event.target;

            // Verificamos que el evento provenga de una celda editable (<td>)
            if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD') {
                const coordenada = target.getAttribute('data-cell');
                const nuevoValor = target.textContent; 

                // 1. LÓGICA: Actualizar el estado con los datos del evento
                actualizarCelda(coordenada, nuevoValor);

                // 2. PERSISTENCIA: Guardar el cambio en local storage
                guardar();

                // 3. DIBUJO: Refrescar la vista (esto recalculará todas las fórmulas)
                render();
            }
        });
    }

    // 2. Listener para selección de columnas (NUEVO)
    const headerRow = document.querySelector('#spreadsheetTable thead tr');
    if (headerRow) {
        headerRow.addEventListener('click', (event) => {
            let target = event.target;

            // Verificamos que el clic haya ocurrido en un selector de columna
            if (target && target.classList.contains('column-selector')) {
                const colChar = target.textContent.trim();
                selectColumn(colChar);
            }
        });
    }

    // 3. Listener para Controles de Columna (NUEVO)
    document.getElementById('clearColumnButton').addEventListener('click', () => {
        if (!estadoSeleccionColumna) return;
        clearColumnContent(estadoSeleccionColumna);
    });

    document.getElementById('deleteColumnButton').addEventListener('click', () => {
        if (!estadoSeleccionColumna) return;
        if (confirm(`¿Está seguro de que desea ELIMINAR completamente la columna ${estadoSeleccionColumna}? Esta acción no se puede deshacer.`)) {
            deleteColumn(estadoSeleccionColumna);
        }
    });

    // Nota: La funcionalidad de cambio de color requiere un botón o input adicional en el HTML. 
    // Se dejó solo la conexión de los botones ya definidos (Clear y Delete).
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
