function handleColumnSelect(event) {
    const target = event.currentTarget;
    const colChar = target.getAttribute('data-column');

    if (!colChar) return;

    // 1. Deseleccionar columna anterior
    document.querySelectorAll('.col-header').forEach(el => el.classList.remove('selected'));

    // 2. Seleccionar nueva columna
    target.classList.add('selected');

    // 3. Actualizar estado interno de la selección (si fuera necesario)
    state.selectedColumn = colChar;

    // 4. Actualizar UI de controles
    document.getElementById('selectedColumnDisplay').textContent = `Columna ${colChar}`;
    const clearButton = document.getElementById('clearColumnButton');
    const deleteButton = document.getElementById('deleteColumnButton');

    if (colChar) {
        clearButton.disabled = false;
        deleteButton.disabled = false;
    } else {
        clearButton.disabled = true;
        deleteButton.disabled = true;
    }

    // 5. Aplicar resaltado visual de la columna seleccionada en todo el cuerpo
    document.querySelectorAll('.row-label').forEach(el => el.closest('tr')).forEach(row => {
        row.classList.remove('column-highlight');
        const cell = row.querySelector(`[data-cell^="${colChar}"]`);
        if (cell) {
            // Esto solo añade la clase al TR si queremos que resalte toda la fila, 
            // pero para resaltar SOLO la columna, debemos aplicar la clase en el TD/TH contenedor.
            const cellContainer = cell.parentNode;
            if (cellContainer && !cellContainer.classList.contains('column-highlight')) {
                 // Si aplicamos esto a cada TR, se sobrepondrá si no es cuidadoso. 
                 // Mejor aplicar la clase directamente al TD que representa la columna seleccionada.
                const cellElement = row.querySelector(`[data-cell^="${colChar}"]`);
                if (cellElement) {
                     cellElement.classList.add('column-highlight');
                }
            }
        }
    });

    // 6. Forzar re-render para aplicar el resaltado si es necesario, aunque el CSS debería manejarlo.
    render();
}
