### FUNCION: deleteSelectedColumn
```js
function deleteSelectedColumn() {
    const colChar = state.selectedColumn;
    if (!colChar) return;

    // 1. LÓGICA: Eliminar todos los datos asociados a esta columna del estado global
    let keysToDelete = [];
    for (const key in state) {
        if (key.toUpperCase().startsWith(colChar)) {
            keysToDelete.push(key);
        }
    }

    // 2. Limpiar el estado
    keysToDelete.forEach(key => delete state[key]);

    // 3. DIBUJO: Eliminar la columna del DOM de forma segura y actualizar el estado visual.
    const table = document.getElementById('spreadsheetTable');
    let columnsToRemove = [];

    // Iteramos sobre las filas (desde 1 hasta 20)
    for (let r = 1; r <= 20; r++) {
        const row = document.querySelector(`#row-${r}`);
        if (!row) continue;

        // Buscamos el TD que pertenece a esta columna y lo eliminamos del DOM
        const cellToRemove = row.querySelector(`[data-cell^="${colChar}"]`);
        if (cellToRemove) {
            columnsToRemove.push(cellToRemove);
            cellToRemove.remove();
        }
    }

    // 4. Actualizar la UI de selección y re-renderizar para limpiar highlights/eventos.
    state.selectedColumn = null;
    document.getElementById('selectedColumnDisplay').textContent = 'Ninguna';
    document.querySelectorAll('.col-header').forEach(el => el.classList.remove('selected'));

    // 5. PERSISTENCIA y DIBUJO: Guardar y refrescar la vista completa (esto asegura que no queden listeners muertos).
    guardar();
    render();
}
