```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/**
 * @type {Object.<string, string>} Mapea coordenadas (e.g., "A1") a su contenido actual.
 */
let estado = {}; 
const CLAVE = "app";

// Nueva clave para rastrear la columna seleccionada por el usuario en la UI
const COL_SELECTED = "columnaSeleccionada"; 

function cargar() { try { const s = localStorage.getItem(CLAVE); if (s) estado = JSON.parse(s); } catch (e) {} }
function guardar() { try { localStorage.setItem(CLAVE, JSON.stringify(estado)); } catch (e) {} }

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el estado interno de una celda específica.
 * @param {string} coordenada - La clave de la celda (ej: "B5").
 * @param {string} valor - El nuevo contenido escrito por el usuario.
 */
function actualizarCelda(coordenada, valor) {
    estado[coordenada] = String(valor); 
}

/**
 * Evalúa una fórmula de estilo Excel en el estado actual del sistema.
 * @param {string} formula - La fórmula ingresada (debe empezar con '=').
 * @param {Object.<string, string>} state - El objeto de estado global (estado[coordenada] = valor).
 * @returns {string} El resultado calculado como cadena, o la fórmula original si no es válida.
 */
function evalFormula(formula, state) {
    if (!formula || !formula.startsWith('=')) {
        return formula; // No es una fórmula, devolverlo tal cual.
    }

    let expression = formula.substring(1).trim();

    // 1. Manejo de SUMA()
    const sumMatch = expression.match(/^SUMA\((.*)\)$/i);
    if (sumMatch) {
        const args = sumMatch[1];
        let valuesToSum = [];

        // Identificar argumentos separados por ; o espacios, manejando rangos A1:A3
        const parts = args.split(/[;,]\s*|\s+/).filter(p => p);

        for (const part of parts) {
            if (part.includes(':')) {
                // Rango simple vertical (e.g., A1:A3)
                const [startRef, endRef] = part.split(':').map(r => r.toUpperCase());

                if (startRef[0] !== endRef[0]) continue; // Debe ser la misma columna

                const startRow = parseInt(startRef.substring(startRef.length - 1));
                const endRow = parseInt(endRef.substring(endRef.length - 1));
                const colChar = startRef[0];

                for (let r = startRow; r <= endRow; r++) {
                    const key = colChar + r;
                    if (state[key] !== undefined) {
                        valuesToSum.push(parseFloat(state[key]));
                    }
                }
            } else {
                // Celda suelta (e.g., B2)
                const key = part.toUpperCase();
                if (state[key] !== undefined) {
                    valuesToSum.push(parseFloat(state[key]));
                }
            }
        }

        const total = valuesToSum.reduce((acc, val) => acc + val, 0);
        return total.toString();
    }


    // 2. Manejo de Operaciones Aritméticas Simples (Ej: =A1-B1, =A1*B1)
    const refRegex = /([A-Z]+[0-9]+)/g;
    let expressionString = expression.replace(refRegex, (match) => {
        // Reemplaza las referencias de celda con sus valores numéricos actuales para poder evaluar la expresión JS
        const value = state[match] !== undefined ? parseFloat(state[match]) : 0;
        return isNaN(value) ? '0' : value;
    });

    try {
        // Usamos new Function() de forma controlada.
        const result = new Function('return ' + expressionString);
        return parseFloat(result()).toString();
    } catch (e) {
        console.error("Error al evaluar la expresión:", e);
        // Si falla la evaluación, devolvemos la fórmula original para que el usuario la vea.
        return formula; 
    }
}

/**
 * Selecciona una columna por su carácter (A, B, C...).
 * @param {string} colChar - El carácter de la columna ('A', 'B', etc.).
 */
function selectColumn(colChar) {
    // Actualiza el estado interno para saber qué columna está activa
    estado[COL_SELECTED] = colChar; 
    guardar(); // Guardamos la selección
}

/**
 * Limpia el contenido de una columna seleccionada.
 * @param {string} colChar - El carácter de la columna a limpiar.
 */
function clearColumn(colChar) {
    const rows = 20;
    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        // Limpiamos el estado y actualizamos la celda en el DOM.
        actualizarCelda(key, "");
    }
    guardar();
}

/**
 * Cambia el color de fondo de una columna completa (aplicación visual).
 * NOTA: Esta función manipula directamente los estilos del DOM porque es un efecto visual global.
 * @param {string} colChar - El carácter de la columna a colorear.
 * @param {string} color - Código hexadecimal o nombre de color.
 */
function setColumnBackgroundColor(colChar, color) {
    const rows = 20;
    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        // Aplicamos el estilo directamente al elemento TD correspondiente
        const cellElement = document.querySelector(`[data-cell="${key}"]`);
        if (cellElement) {
            cellElement.style.backgroundColor = color;
        }
    }
    // No actualizamos 'estado' porque es un estilo visual, no datos de contenido. 
    // Pero sí llamamos a render para asegurar que el estado se refleje si hay cambios en la lógica de dibujo.
}

/**
 * Borra una columna completamente (borrado conceptual). 
 * NOTA: Por simplicidad y minimización de cambios críticos, esta función solo limpia datos y resetea estilos, pero no re-indexa DOM ni estados dependientes.
 * @param {string} colChar - El carácter de la columna a borrar.
 */
function deleteColumn(colChar) {
    // 1. Limpiar el estado interno para toda la columna
    const rows = 20;
    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        delete estado[key];
    }

    // 2. Resetear los estilos visuales en el DOM (esto se haría idealmente con CSS o un método más avanzado de renderizado, pero aquí lo hacemos explícito)
    for (let r = 1; r <= rows; r++) {
        const key = colChar + r;
        const cellElement = document.querySelector(`[data-cell="${key}"]`);
        if (cellElement) {
            cellElement.style.backgroundColor = ''; // Remover color de fondo
        }
    }

    guardar();
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    const rows = 20;
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(''); // A-J (10 chars)

    // Limpiar cualquier estilo de columna previamente seleccionado para evitar residuos visuales al renderizar datos puros.
    document.querySelectorAll('.column-header').forEach(th => {
        th.classList.remove('selected-column'); 
        th.style.backgroundColor = ''; // Reset color background
    });

    // Si hay una columna seleccionada, re-aplicar el estilo de selección (este es un efecto UI/UX)
    const selectedColChar = estado[COL_SELECTED];
    if (selectedColChar && document.querySelector(`.column-header[data-col-char="${selectedColChar}"]`)) {
        document.querySelector(`.column-header[data-col-char="${selectedColChar}"]`).classList.add('selected-column');
    }


    for (let r = 1; r <= rows; r++) {
        const rowElement = tableBody.querySelector(`tr:nth-child(${r})`);
        if (!rowElement) continue;

        for (let c = 0; c < columns.length; c++) {
            const columnaChar = columns[c];
            const coordenada = columnaChar + r;
            const cellElement = rowElement.querySelector(`[data-cell="${coordenada}"]`);

            if (cellElement) {
                // Obtener el valor de estado, si no existe, es una cadena vacía.
                const contenido = estado[coordenada] || ""; 
                let contenidoMostrar = contenido;

                // Evaluar la fórmula antes de mostrarla en el DOM
                if (contenido.startsWith('=')) {
                    contenidoMostrar = evalFormula(contenido, estado);
                } else {
                     // Aseguramos que el color de fondo no se pierda si está definido externamente 
                     // (ej. por setColumnBackgroundColor) pero el contenido es vacío en el estado.
                     cellElement.style.backgroundColor = ''; // Limpiar cualquier estilo previo al renderizar datos puros
                }

                // Actualizar el DOM con el contenido calculado o original.
                cellElement.textContent = contenidoMostrar;
            }
        }
    }
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tableContainer = document.getElementById('spreadsheetTable');
    const headerRow = document.querySelector('#columnHeaders tr');

    if (tableContainer) {
        // 1. Listener para cambios en celdas editable (Input Event)
        tableContainer.addEventListener('input', (event) => {
            let target = event.target;

            // Verificamos que el evento provenga de una celda editable (<td>)
            if (target && target.hasAttribute('contenteditable') && target.tagName === 'TD') {
                const coordenada = target.getAttribute('data-cell');
                const nuevoValor = target.textContent; 

                // 1. LÓGICA: Actualizar el estado con los datos del evento
                actualizarCelda(coordenada, nuevoValor);

                // 2. PERSISTENCIA: Guardar el cambio en local storage
                guardar();

                // 3. DIBUJO: Refrescar la vista (esto recalculará todas las fórmulas)
                render();
            }
        });
    }

    // 2. Listener para selección de columna (Click Event en encabezados)
    if (headerRow) {
         headerRow.addEventListener('click', (event) => {
             const target = event.target;

             if (target && target.classList.contains('column-header') && target.hasAttribute('data-col-char')) {
                 const colChar = target.getAttribute('data-col-char');

                 // 1. LÓGICA: Seleccionar la columna en el estado global
                 selectColumn(colChar);

                 // Mostrar un panel de acciones debajo del contenedor principal para usar los controles (esto es UI, no lógica)
                 document.getElementById('columnActionsContainer').style.display = 'flex';

                 // 2. DIBUJO: Refrescar la vista para aplicar el estilo visual de selección
                 render();
             }
         });
    }


    // 3. Listener para botones de acción (delegación)
    const actionsContainer = document.getElementById('columnActionsContainer');
    if (actionsContainer) {
        actionsContainer.addEventListener('click', (event) => {
            const target = event.target;
            let colChar = estado[COL_SELECTED];

            if (!colChar) return; // No hay columna seleccionada

            // Acción de Borrar Contenido
            if (target.dataset.action === 'clear') {
                clearColumn(colChar);
                guardar();
                render();
            } 
            // Acción de Colorear Fondo
            else if (target.dataset.action === 'color' && target.dataset.hex) {
                const color = target.dataset.hex;
                setColumnBackgroundColor(colChar, color);
                // No se requiere guardar estado, solo render para asegurar la visualización
                render(); 
            }
            // Acción de Borrar Columna (Solo limpieza lógica y visual simple)
            else if (target.dataset.action === 'delete') {
                if (confirm(`¿Está seguro que desea borrar todos los datos de la columna ${colChar}? Esta acción es irreversible en el estado.`)) {
                    deleteColumn(colChar);
                    guardar();
                    render();
                }
            }
        });
    }
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
