function deleteSelectedColumn() {
    const colChar = estado.selectedColumn;
    if (!colChar) return;

    // 1. LÓGICA: Borrar contenido de la columna en el estado
    let keysToDelete = [];
    for (const key in estado) {
        if (key.startsWith(colChar + '')) {
            keysToDelete.push(key);
        }
    }
    keysToDelete.forEach(key => delete estado[key]);

    // 2. DIBUJO: Eliminar las celdas y actualizar la estructura del DOM
    const table = document.getElementById('spreadsheetTable');
    let colIndex = 'A'.charCodeAt(0) - 'A'.charCodeAt(0); // Start index (A=0)
