    // Iterar sobre todas las filas y eliminar la celda correspondiente
    document.querySelectorAll(`[data-col="${colChar}"]`).forEach(cell => {
        cell.remove();
    });

    // 3. AJUSTE DE ESTRUCTURA: Reajustar los encabezados de columna (A, B, C...)
    const headerRow = document.getElementById('spreadsheetTable').querySelector('thead tr');
