function selectColumn(colChar) {
    // 1. UI: Update controls visibility and labels
    const columnHeaders = document.querySelectorAll('.column-header');
    columnHeaders.forEach(header => header.classList.remove('selected'));

    // Select the clicked header visually
    const selectedHeader = document.querySelector(`.column-header[data-col-char="${colChar}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    document.getElementById('selectedColumnLabel').textContent = colChar;
    document.getElementById('colorPicker').value = '#ffffff'; // Reset color picker
    document.getElementById('columnControls').classList.remove('hidden');

    // 2. State: Store the selected column
    window.selectedColumn = colChar;

    // 3. Logic/Drawing: Apply selection styles to all cells in this column (visual only)
    const rows = document.querySelectorAll('#spreadsheetTable tbody tr');
    rows.forEach(row => {
        const cellElement = row.querySelector(`[data-cell*="${colChar}"]`);
        if (cellElement) {
            // Apply a selection background class/style
            cellElement.classList.add('selected-column-cell');
        }
    });

    // Ensure the state variable is globally accessible for event listeners in 'conectar'
    window.selectedColumn = colChar; 
}
