/**
 * Limpia el contenido de una fila específica (A-J).
 * @param {number} rowNumber - El número de la fila a limpiar.
 */
function clearRow(rowNumber) {
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');
    let coordinatesToClear = [];

    for (let c = 0; c < columns.length; c++) {
        const columnaChar = columns[c];
        const coordenada = columnaChar + rowNumber;
        coordinatesToClear.push(coordenada);
        // Limpiar el estado
        delete estado[coordenada];
    }

    // Actualizar la vista y guardar los cambios
    render(); 
    guardar();
}
