 * @param {number} rowNumber - El número de la fila a eliminar.
 */
function deleteRow(rowNumber) {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    // 1. Eliminar el elemento del DOM (usando nth-child para consistencia con los datos)
    const rowElement = tableBody.querySelector(`tr:nth-child(${rowNumber})`);
    if (rowElement) {
        rowElement.remove();
    }

    // 2. Limpiar el estado interno para todas las coordenadas de esa fila
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');
    for (let c = 0; c < columns.length; c++) {
        const columnaChar = columns[c];
        const coordenada = columnaChar + rowNumber;
        delete estado[coordenada];
    }

    // 3. Guardar y renderizar para limpiar cualquier artefacto visual
    guardar();
    render(); 
}
