function handleRowSelection(rowNum) {
    // 1. Deseleccionar cualquier fila previamente activa
    document.querySelectorAll('.row-label').forEach(el => el.classList.remove('selected'));
    document.getElementById('clearRowBtn').disabled = true;
    document.getElementById('colorChangeBtn').disabled = true;
    document.getElementById('deleteRowBtn').disabled = true;

    // 2. Seleccionar la nueva fila y actualizar controles/estado visual
    const targetLabel = document.querySelector(`.row-label[data-row="${rowNum}"]`);
    if (targetLabel) {
        targetLabel.classList.add('selected');

        // Habilitar controles
        document.getElementById('clearRowBtn').disabled = false;
        document.getElementById('colorChangeBtn').disabled = false;
        document.getElementById('deleteRowBtn').disabled = false;

        // Almacenar el número de fila seleccionado globalmente (o en un estado más complejo si fuera necesario)
        window._selectedRowNum = rowNum; 
    } else {
         window._selectedRowNum = null;
    }
}
