 */
function selectRow(rowNumber) {
    // 1. LÓGICA: Actualizar el estado de la fila seleccionada.
    estado['selectedRow'] = rowNumber;

    // 2. DIBUJO: Resaltar visualmente la fila en el DOM (solo afecta a los labels).
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    // Deseleccionar todas las filas primero
    Array.from(tableBody.querySelectorAll('.row-label')).forEach(el => {
        el.classList.remove('selected');
    });

    // Seleccionar la fila específica
    const selectedLabel = tableBody.querySelector(`.row-label[data-row="${rowNumber}"]`);
    if (selectedLabel) {
        selectedLabel.classList.add('selected');
    }
}

/**
 * Limpia el contenido de todas las celdas en la fila seleccionada y actualiza el estado.
 */
function clearSelectedRow() {
    const row = estado['selectedRow'];
    if (!row) return;

    // 1. LÓGICA: Limpiar el contenido de todas las celdas en la fila seleccionada.
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');
    for (let i = 0; i < columns.length; i++) {
        const colChar = columns[i];
        const coordenada = colChar + row;

        // Limpiar el estado y actualizar el contenido visualmente.
