}


/**
 * Elimina el contenido de la fila seleccionada del estado y resetea su visualización.
 */
function deleteSelectedRow() {
    const row = estado['selectedRow'];
    if (!row) return;

    // 1. LÓGICA: Vaciar los datos de la fila en el estado.
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split('');
    for (let i = 0; i < columns.length; i++) {
        const colChar = columns[i];
        const coordenada = colChar + row;

        // Solo vaciar si existía contenido para simular la eliminación de datos.
        if (estado[coordenada] !== undefined) {
             actualizarCelda(coordenada, "");
        }
    }

    // 2. PERSISTENCIA: Guardar los cambios (vacío).
    guardar();

    // 3. DIBUJO: Refrescar la vista y resetear selección.
    render();
    selectRow(null); 
}


/**
 * Cambia el color de fondo de todas las celdas en la fila seleccionada.
 * @param {number} rowNumber - El número de la fila (1-based index).
 * @param {string} color - Código hexadecimal del color (#RRGGBB).
 */
function setRowBackgroundColor(rowNumber, color) {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody || !rowNumber) return;

    // 1. DIBUJO/ESTILO: Aplicar el estilo a todas las celdas de la fila seleccionada.
    const rowCells = Array.from(tableBody.querySelectorAll(`tr:nth-child(${rowNumber}) td`));

    if (color) {
        // Si se pasa un color, lo aplicamos y limpiamos colores anteriores.
        rowCells.forEach(cell => {
            cell.style.backgroundColor = color;
        });
    } else {
        // Limpiar fondo si el color es nulo o blanco por defecto.
        rowCells.forEach(cell => {
             cell.style.backgroundColor = '';
        });
    }

    // 2. DIBUJO: Asegurar que la selección y render sean correctos después del cambio de estilo.
    selectRow(rowNumber);
    render(); 
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    const rows = 20;
    const columns = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split(''); // A-J (10 chars)

    for (let r = 1; r <= rows; r++) {
        // Usamos querySelector para obtener la fila por índice de tr:nth-child(r)
        const rowElement = tableBody.querySelector(`tr:nth-child(${r})`);
        if (!rowElement) continue;

        for (let c = 0; c < columns.length; c++) {
            const columnaChar = columns[c];
            const coordenada = columnaChar + r;
            // Buscamos la celda específica por data-cell
            const cellElement = rowElement.querySelector(`[data-cell="${coordenada}"]`);

            if (cellElement) {
                // Obtener el valor de estado, si no existe, es una cadena vacía.
                const contenido = estado[coordenada] || ""; 
                let contenidoMostrar = contenido;

                // Evaluar la fórmula antes de mostrarla en el DOM
                if (contenido.startsWith('=')) {
                    contenidoMostrar = evalFormula(contenido, estado);
                } else {
                    // Asegurar que las celdas no muestren texto si están vacías y no son fórmulas
                    contenidoMostrar = contenido; 
                }

                // Actualizar el DOM con el contenido calculado o original.
                cellElement.textContent = contenidoMostrar;
            }
        }
    }
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const tableContainer = document.getElementById('spreadsheetTable');

    if (tableContainer) {
        // 1. Delegación para inputs en celdas (<td contenteditable>)
        tableContainer.addEventListener('input', (event) => {
