                const nuevoValor = target.textContent; 

                // LÓGICA: Actualizar el estado con los datos del evento
                actualizarCelda(coordenada, nuevoValor);

                // PERSISTENCIA: Guardar el cambio en local storage
                guardar();

                // DIBUJO: Refrescar la vista (esto recalculará todas las fórmulas)
                render();
