        // 2. Delegación para clics en etiquetas de fila (Row Labels)
        tableContainer.addEventListener('click', (event) => {
             let target = event.target;
             // Verificamos que el clic provenga del elemento con la clase row-label y data-row
            if (target && target.classList.contains('row-label') && target.hasAttribute('data-row')) {
                const rowNumber = parseInt(target.getAttribute('data-row'));
                selectRow(rowNumber);
            }
        });

        // 3. Delegación para botones de acción (incluyendo los nuevos controles)
        tableContainer.addEventListener('click', (event) => {
