        let columnThsHtml = '<th class="corner-cell"></th>'; // Corner cell always present
        for(let i=0; i<columns.length; i++){
            columnThsHtml += `<th>${columns[i]}</th>`;
        }
        // Esto requiere modificar la estructura del thead, lo cual es complicado con el DOM actual. 
        // Por simplicidad y mínimo cambio: asumiremos que los encabezados A-J ya están en el HTML estático (index.html)
    }


    // --- Generar Filas y Celdas de Datos ---

    for (let r = 1; r <= rows; r++) {
        const rowNumberStr = String(r);
        if (!estado.visibleRows.includes(rowNumberStr)) continue; // Saltar si la fila está oculta

        // Crear la fila TR para el DOM
        const rowElement = document.createElement('tr');
        let rowHtml = ''; 

        // 1. Celda de etiqueta de fila (el número)
        let rowLabelTh = `<th class="row-label">${rowNumberStr}</th>`;

        // 2. Contenido de las celdas visibles
        const visibleCells = [];
        for (let i = 0; i < columns.length; i++) {
            const columnaChar = columns[i];
            const coordenada = columnaChar + rowNumberStr;

            // Obtener el valor de estado, si no existe, es una cadena vacía.
            const contenido = estado[coordenada] || ""; 
            let contenidoMostrar = contenido;

            // Evaluar la fórmula antes de mostrarla en el DOM
            if (contenido.startsWith('=')) {
                contenidoMostrar = evalFormula(contenido, estado);
            }
            visibleCells.push(`<td data-cell="${coordenada}" contenteditable="true">${contenidoMostrar}</td>`);
        }

        // Ensamblar la fila completa con el contenido visible
        rowElement.innerHTML = rowLabelTh + visibleCells.join('');
        tableBody.appendChild(rowElement);
    }

    // Nota: Dado que estamos re-renderizando todo, necesitamos asegurarnos de que los listeners de 'input' vuelvan a funcionar en las nuevas celdas creadas. 
    // Esto se maneja mejor si el evento delegador está bien configurado (lo cual sí lo está en conectar()).
}
