function toggleRowVisibility(rowIndex) {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    // Determinar el estado actual de visibilidad del índice (usaremos un atributo data-hidden en el <tr>)
    const rowElement = tableBody.querySelector(`tr:nth-child(${rowIndex})`);
    if (!rowElement) {
        console.warn(`Fila ${rowIndex} no encontrada.`);
        return;
    }

    const isHidden = rowElement.hasAttribute('data-hidden');
    let displayStyle = isHidden ? 'table-row' : 'none';

    // 1. Actualizar el DOM
    if (isHidden) {
        rowElement.style.display = 'table-row';
        rowElement.removeAttribute('data-hidden');
    } else {
        rowElement.style.display = 'none';
        rowElement.setAttribute('data-hidden', 'true');
    }

    // 2. Actualizar la visibilidad de los encabezados (columna A) y etiquetas de fila
    const rowLabelCell = document.querySelector(`.row-label[data-row="${rowIndex}"]`);
    if (rowLabelCell) {
        rowLabelCell.style.display = isHidden ? 'table-cell' : 'none';
    }

    // 3. Recalcular y guardar el estado para que las fórmulas se ajusten al render() siguiente.
    // No necesitamos cambiar `estado`, solo la vista.
    guardar();
    render();
}
