function toggleColumnVisibility(colChar) {
    const tableBody = document.querySelector("#spreadsheetTable tbody");
    if (!tableBody) return;

    // 1. Iterar sobre todas las filas para ocultar/mostrar celdas
    let isHidden = false;
    for (let r = 1; r <= 20; r++) {
        const rowElement = tableBody.querySelector(`tr:nth-child(${r})`);
        if (!rowElement) continue;

        // Encontrar la celda de la columna actual en esta fila
        const cellToToggle = rowElement.querySelector(`[data-cell="${colChar}${r}"]`);
        if (cellToToggle) {
            let displayStyle = isHidden ? 'table-cell' : 'none';

            // Actualizar el DOM para esa celda específica
            cellToToggle.style.display = displayStyle;
        }
    }

    // 2. Actualizar la visibilidad del encabezado de columna (A, B, C...)
    const colHeaderElement = document.querySelector(`.col-header[data-col-char="${colChar}"]`);
    if (colHeaderElement) {
        colHeaderElement.style.display = isHidden ? 'table-header' : 'none';
    }

    // 3. Guardar y renderizar para asegurar que la vista se actualice correctamente.
    guardar();
    render();
}
