    const rowLabel = document.querySelector(`.row-label:contains("${rowNumber}")`);
    if (!rowLabel) return;

    // Encontrar el <tr> padre que contiene el label y las celdas de datos
    const rowElement = rowLabel.closest('tr');
    if (!rowElement) return;

    if (hide) {
        rowElement.style.display = 'none';
    } else {
        rowElement.style.display = ''; // Restaurar al display por defecto
    }
}
```

### FUNCION: toggleColumnVisibility
```js
function toggleColumnVisibility(colLetter, hide) {
    const table = document.getElementById('spreadsheetTable');
    if (!table) return;

    // 1. Ocultar las cabeceras de columna (Thead)
    const headerCells = table.querySelector('thead th');
    headerCells.forEach(th => {
        if (th.getAttribute('data-col') === colLetter) {
            th.style.display = hide ? 'none' : '';
        }
    });

    // 2. Ocultar las celdas de datos en el cuerpo (Tbody)
    const bodyRows = table.querySelectorAll('tbody tr');
    bodyRows.forEach(row => {
        const cells = row.querySelectorAll('td');
        cells.forEach(cell => {
            if (cell.getAttribute('data-col') === colLetter) {
                cell.style.display = hide ? 'none' : '';
            }
        });
    });
}
```

