    padding: 8px 15px;
    cursor: pointer;
    border: 1px solid #ccc;
    background-color: #f9f9f9;
    transition: background-color 0.2s;
}

.controls button:hover {
    background-color: #e0e0e0;
}


/* Estilos de la tabla */
#spreadsheetTable {
    border-collapse: collapse;
    width: fit-content; /* Permite que la tabla crezca horizontalmente */
}

th, td {
    border: 1px solid #ccc;
    padding: 8px;
    min-width: 50px; /* Asegura un ancho mínimo para las celdas de datos */
    height: 30px; /* Altura fija para las filas */
    box-sizing: border-box;
}

/* Estilo para la esquina superior izquierda (Corner cell) */
#spreadsheetTable th:first-child {
    background-color: #f0f0f0;
    font-weight: bold;
}

/* Etiqueta de Fila (Row Label) */
.row-label {
    background-color: #e9e9e9;
    text-align: center;
    width: 40px; /* Ancho fijo para los números de fila */
    font-weight: bold;
}

/* Estilo para las celdas editables */
[contenteditable="true"] {
    outline: none; /* Eliminar el borde azul al hacer clic */
}

/* Asegurar que el contenido calculado no sea visible si la celda está oculta (aunque JS lo maneja, es buena práctica) */
.hidden {
